mapper.sql:
SELECT id, agent_name, agent_key, is_system, description, system_prompt, content, temperature, max_tokens, status, version, created_by, published_at, created_at, updated_at FROM sys_agents WHERE 1=1 AND status = #{status} AND is_system = #{isSystem}
AND (agent_name LIKE #{keyword} OR agent_key LIKE #{keyword} OR description LIKE #{keyword})
ORDER BY id DESC

