UPDATE sys_agents
agent_name = #{row['agentName']}, agent_key = #{row['agentKey']}, is_system = #{row['isSystem']}, description = #{row['description']}, system_prompt = #{row['systemPrompt']}, content = #{row['content']}, temperature = #{row['temperature']}, max_tokens = #{row['maxTokens']}, status = #{row['status']}, updated_at = NOW()
WHERE id = #{id}
